import { isImageFile, isVideoFile, isAudioFile } from '@/utils/mimeTypes';
import { formatLocationAddress } from '@/utils/reverseGeocode';
export default {
  name: 'FileCard',
  props: {
    item: {
      type: Object,
      required: true
    },
    selected: {
      type: Boolean,
      default: false
    },
    fileLink: {
      type: String,
      required: true
    },
    previewSrcList: {
      type: Array,
      default: () => []
    },
    disableTooltip: {
      type: Boolean,
      default: false
    }
  },
  emits: ['update:selected', 'detail', 'copy', 'move', 'delete', 'download', 'touchstart', 'touchend', 'touchmove', 'locationClick'],
  data() {
    return {
      localSelected: this.selected,
      videoLoading: true,
      videoError: false
    };
  },
  computed: {
    channelTag() {
      return this.item.channelTag || '';
    },
    isVideo() {
      return isVideoFile(this.item);
    },
    isAudio() {
      return isAudioFile(this.item);
    },
    isImage() {
      return isImageFile(this.item);
    },
    displayName() {
      const fileName = this.item.metadata?.FileName || this.item.name || '';
      const parts = fileName.split('/');
      return parts[parts.length - 1];
    },
    hasLocation() {
      const lat = this.item?.metadata?.Latitude ?? this.item?.metadata?.latitude;
      const lng = this.item?.metadata?.Longitude ?? this.item?.metadata?.longitude;
      return lat !== undefined && lat !== null && lat !== '' && lng !== undefined && lng !== null && lng !== '';
    },
    locationDisplayText() {
      const rawLoc = this.item?.metadata?.LocationName || this.item?.metadata?.location_name;
      const locName = formatLocationAddress(rawLoc);
      if (locName) {
        return locName;
      }
      const rawLat = this.item?.metadata?.Latitude ?? this.item?.metadata?.latitude;
      const rawLng = this.item?.metadata?.Longitude ?? this.item?.metadata?.longitude;
      const lat = parseFloat(rawLat);
      const lng = parseFloat(rawLng);
      if (!isNaN(lat) && !isNaN(lng)) {
        return `${lat.toFixed(1)}°, ${lng.toFixed(1)}°`;
      }
      return this.$t('dashboard.hasLocation') || 'GPS';
    },
    locationTooltip() {
      const rawLoc = this.item?.metadata?.LocationName || this.item?.metadata?.location_name || '';
      const name = formatLocationAddress(rawLoc);
      const lat = this.item?.metadata?.Latitude ?? this.item?.metadata?.latitude;
      const lng = this.item?.metadata?.Longitude ?? this.item?.metadata?.longitude;
      if (name && lat && lng) {
        return `${name} (${lat}, ${lng})`;
      }
      if (lat && lng) {
        return `${lat}, ${lng}`;
      }
      return name;
    }
  },
  watch: {
    selected(val) {
      this.localSelected = val;
    },
    fileLink() {
      // 链接变化时重置加载状态
      this.videoLoading = true;
      this.videoError = false;
    }
  },
  methods: {
    handleLocationClick() {
      this.$emit('locationClick', this.item);
    },
    handleVideoError() {
      this.videoLoading = false;
      this.videoError = true;
    },
    handleVideoClick(e) {
      const video = e.target;
      if (video.requestFullscreen) {
        video.requestFullscreen();
      } else if (video.webkitRequestFullscreen) {
        video.webkitRequestFullscreen();
      } else if (video.mozRequestFullScreen) {
        video.mozRequestFullScreen();
      } else if (video.msRequestFullscreen) {
        video.msRequestFullscreen();
      }
    },
    handleFullscreenChange(e) {
      const video = e.target;
      const isFullscreen = document.fullscreenElement || document.webkitFullscreenElement || document.mozFullScreenElement || document.msFullscreenElement;
      if (isFullscreen) {
        // 进入全屏：取消静音和循环
        video.muted = false;
        video.loop = false;
      } else {
        // 退出全屏：恢复静音和循环，暂停并重置
        video.muted = true;
        video.loop = true;
        video.pause();
        video.currentTime = 0;
      }
    },
    handleVideoHover(e, isEnter) {
      const video = e.target;
      if (isEnter) {
        video.play().catch(() => {});
      } else {
        video.pause();
        video.currentTime = 0;
      }
    }
  }
};